62	export function appliedSummary(setup: AppliedSetupInfo | null | undefined): string[] {
63	  if (!setup || setup.printableObjects === 0) return [];
64	  if (setup.spiralMode) return ['Spiral vase mode'];
65	  const layer = setup.variableLayerHeight ? 'Variable layer height' :
66	    factText(fact(setup, 'layer_height'), (value) => `${millimetres(value)} layers`,
67	      'Layer height varies by object', 'Local layer heights');
68	  const walls = factText(fact(setup, 'wall_loops'), (value) => `${value} ${value === '1' ? 'wall' : 'walls'}`,
69	    'Walls vary by object', 'Local wall settings');
70	  const density = fact(setup, 'sparse_infill_density');
71	  const pattern = fact(setup, 'sparse_infill_pattern');
72	  const infill = factText(density, (value) => {
73	    const percent = Number.parseFloat(value);
74	    if (percent === 0) return 'No sparse infill';
75	    if (percent === 100) return '100% infill';
76	    const patternText = pattern?.coverage === 'exact' && pattern.value ? ` ${pattern.value.replaceAll('_', ' ')}` : '';
77	    return `${value}${patternText} infill`;
78	  }, 'Infill varies by object', 'Local infill settings');
79	  const enabled = fact(setup, 'enable_support');
80	  const supportType = fact(setup, 'support_type');
81	  const plateOnly = fact(setup, 'support_on_build_plate_only');
82	  const supports = factText(enabled, (value) => {
