99	export function estimateFacts(context: WorkspaceContext): { text: string; note: string; previous: string } {
100	  const plate = context.plates.find((item) => item.active);
101	  if (!plate) return { text: 'Estimate unavailable', note: '', previous: '' };
102	  const estimate = plate.estimate;
103	  const values: string[] = [];
104	  if (estimate) {
105	    if (estimate.timeAvailable ?? estimate.printTimeSeconds > 0) values.push(formatPrintTime(estimate.printTimeSeconds));
106	    if (estimate.materialAvailable ?? estimate.materialGrams > 0) values.push(formatGrams(estimate.materialGrams));
107	  }
108	  const joined = values.join(' · ');
109	  if (plate.estimateStatus === 'recomputing')
110	    return { text: 'Time & material estimates recomputing…', note: '', previous: joined };
111	  if (plate.estimateStatus === 'stale')
112	    return { text: joined ? 'Previous estimates · not current' : 'Estimate out of date',
113	      note: plate.invalidatedBy || '', previous: joined };
114	  if (joined) return { text: joined, note: '', previous: '' };
115	  return { text: plate.sliced ? 'Estimate unavailable' : 'Not sliced yet · estimates unavailable', note: '', previous: '' };
116	}
