118	export function deterministicAttention(context: WorkspaceContext): { title: string; detail: string }[] {
119	  const review = context.printerReview;
120	  if (!review) return [];
121	  const priority: Record<string, number> = { filament: 0, nozzle: 1, model: 2, plate: 3 };
122	  return [...review.mismatches].sort((a, b) =>
123	    (priority[a.what] ?? 4) - (priority[b.what] ?? 4)).flatMap((mismatch) => {
124	    const reported = mismatch.source === 'device';
125	    if (reported && !review.observed?.observedAt) return [];
126	    const title = mismatch.what === 'filament' ? 'Material needs review' :
127	      mismatch.what === 'plate' ? 'Build plate needs review' : 'Printer setup needs review';
128	    const source = reported ? `Last reported ${review.observed?.observedAt}` : 'User confirmed';
129	    return [{ title, detail: `${source}: configured ${mismatch.configured}; ${
130	      reported ? 'printer reported' : 'confirmed'} ${mismatch.observed}.` }];
131	  });
132	}
