1	// The setup card: what the agent heard, what it will cost, and how far the
2	// project has drifted from its preset. It sits above the thread and every
3	// pixel it takes comes out of the conversation, so it rests at three lines and
4	// grows only for something you have not seen.
5	//
6	// Each row has its own presence rule, and every fallback ends in omitting the
7	// row -- never a placeholder, a zero, or a guess. Missing data therefore makes
8	// the card shorter, never broken. When every optional row is gone the kicker
9	// goes too: a heading over one line is furniture, and what is left is a label
10	// rather than a card.
11	
12	import { ChangeInfo, PresetDeltaInfo, WorkspaceContext } from '../bridge/protocol';
13	import { AppliedSetupCard } from './AppliedSetupCard';
14	
15	export interface SetupCardProps {
16	  context: WorkspaceContext | null;
17	  expanded: boolean;
18	  onToggle: () => void;
19	  // The agent is mid-thought. The card greys but does not empty: what it shows
20	  // is still exactly what Slice would produce this second, so the invariant
21	  // holds even while the answer is being written.
22	  working?: boolean;
23	  historical?: boolean;
24	  savedAt?: string;
25	  onCompute?: () => void;
26	  attention?: { title: string; detail: string }[];
27	  recentChange?: ChangeInfo;
28	  sentSnapshot?: boolean;
29	}
30	
31	// "~3h 50" over an hour, "~50 min" under it. Seconds are never shown: the
32	// number is an estimate and false precision reads as a promise.
33	export function formatPrintTime(seconds: number): string {
34	  const minutes = Math.round(seconds / 60);
35	  if (minutes < 60) return `~${minutes} min`;
36	  return `~${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}`;
37	}
38	
39	export function formatGrams(grams: number): string {
40	  return `${grams < 10 ? Math.round(grams * 10) / 10 : Math.round(grams)} g`;
41	}
42	
43	// OrcaSlicer has no currency concept -- filament_cost's unit is literally
44	// "money/kg" -- so the host reads the ISO code from the machine's regional
45	// settings and the page formats it the way that viewer's locale writes money:
46	// symbol placement, grouping, and the right number of decimals (yen has none).
47	// Without a code there is nothing to denominate the number in, so it carries
48	// the word "cost" the way the slicer's own G-code legend does.
49	export function formatCost(cost: number, currency: string): string {
50	  if (currency) {
51	    try {
52	      return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cost);
53	    } catch {
54	      // An unknown code is not worth losing the number over.
55	    }
56	  }
57	  return `cost ${cost.toFixed(2)}`;
58	}
59	
60	interface CardModel {
61	  kicker: boolean;
62	  // 2c: the figure a running slice is about to replace, struck through, with
63	  // "re-slicing..." beside it on the same line. The number stays because the
64	  // reader is watching for the difference, and a blank kills the comparison.
65	  struckEstimate: string;
66	  inlineNote: string;
67	  // 2d: the estimate reads plainly -- it is the last honest figure, not a
68	  // discarded one -- and a plain-language row underneath says what took it.
69	  reason: string;
70	  outOfDate: boolean;
71	  // 2e: how many of the deltas you made by hand. Shown only when the agent
72	  // made some of the others -- with nothing to stand apart from, "+7 yours"
73	  // over "7 changes from preset" says the same thing twice.
74	  yours: number;
75	  title: string;
76	  identity: string;
77	  summary: string;
78	  facts: string[];
79	  deltas: PresetDeltaInfo[];
80	  deltaLabel: string;
81	  preset: string;
82	  material: string;
83	}
84	
85	// Everything the card decides about itself, derived once so the resting card
86	// and the expansion cannot disagree about what is present.
87	export function cardModel(context: WorkspaceContext): CardModel {
88	  const active = context.plates.find((plate) => plate.active) ?? null;
89	  const estimate = active?.estimate ?? null;
90	  const deltas = context.presetDeltas;
91	  const title = context.setupIntent.trim();
92	  // The deltas are measured against the process preset, so that is the name
93	  // the card shows -- never the printer, which already lives in the top bar.
94	  // A printer with no process preset has no process settings to drift from
95	  // either, so there is nothing here to name and the card says nothing.
96	  const preset = context.printer.process.trim();
97	  // The material the plan is written against, so a filament change shows up here as
98	  // well as on the chip. The "@printer" qualifier is dropped as the chip drops
99	  // it: it disambiguates presets in a settings list and says nothing here.
100	  const material = context.printer.filament.split('@')[0].trim();
101	
102	  const status = active?.estimateStatus ?? 'current';
103	  const changeWord = deltas.length === 1 ? 'change' : 'changes';
104	  const deltaLabel = deltas.length === 0 ? '' :
105	    status === 'recomputing' ? `${deltas.length} ${changeWord}`
106	                             : `${deltas.length} ${changeWord} from preset`;
107	
108	  // A card earns its heading by having something to say. The preset name on
109	  // its own does not count: nothing was delegated and nothing has moved, so
110	  // what is left is a label and the caller renders it as one.
111	  const substantive = Boolean(title) || estimate !== null || deltaLabel !== '';
112	
113	  const identity = !title && preset && substantive ? preset : '';
114	  const wall = deltas.find((delta) => delta.label === 'Wall loops')?.value;
115	  const density = deltas.find((delta) => delta.label === 'Sparse infill density')?.value;
116	  const pattern = deltas.find((delta) => delta.label === 'Sparse infill pattern')?.value;
117	  const mainSettings = [wall && `${wall} walls`, density && `${density} ${pattern || 'infill'}`].filter(Boolean);
118	  const summary = mainSettings.length > 0 ? mainSettings.join(' · ')
119	    : deltas.slice(0, 2).map((delta) => `${delta.label} ${delta.value}`).join(' · ');
120	
121	  const recomputing = estimate !== null && status === 'recomputing';
122	  const outOfDate = estimate !== null && status === 'stale';
123	
124	  const hand_edited = deltas.filter((delta) => delta.origin === 'user').length;
125	  const yours = hand_edited > 0 && hand_edited < deltas.length ? hand_edited : 0;
126	
127	  const facts: string[] = [];
128	  // Stale keeps its figure on the facts line, unstruck: it is the last number
129	  // the card could defend, not one already superseded by a better answer.
130	  if (estimate && !recomputing) {
131	    facts.push(formatPrintTime(estimate.printTimeSeconds));
132	    facts.push(formatGrams(estimate.materialGrams));
133	    // A priced job so small it rounds to nothing reads exactly like the
134	    // unpriced case, so it takes the same exit: no clause rather than 0.00.
135	    if (estimate.materialCost !== null && estimate.materialCost >= 0.005)
136	      facts.push(formatCost(estimate.materialCost, context.currency));
137	  }
138	
139	  const struckEstimate = recomputing && estimate
140	    ? [formatPrintTime(estimate.printTimeSeconds), formatGrams(estimate.materialGrams)].join(' · ')
141	    : '';
142	  const inlineNote = recomputing ? 're-slicing…' : '';
143	  // Names the action when it is known and asks for the re-slice either way,
144	  // rather than attributing the loss to something the reader did not do.
145	  const reason = outOfDate ? (active?.invalidatedBy ?? '') : '';
146	  // "Not sliced yet" is a claim about the plate, not about whether we happen
147	  // to hold a number: a sliced plate that yielded no usable estimate must not
148	  // be described as unsliced. With no plate at all there is nothing to say.
149	  if (substantive && !estimate && active !== null && !active.sliced) facts.push('not sliced yet');
150	
151	  return { kicker: substantive, title, identity, summary, facts, deltas, deltaLabel, preset, material,
152	           struckEstimate, inlineNote, reason, outOfDate, yours };
153	}
154	
155	function DeltaList({ deltas }: { deltas: PresetDeltaInfo[] }) {
156	  return (
157	    <dl className="current-setup-deltas">
158	      {deltas.map((delta) => (
159	        <div key={delta.key}>
160	          <dt title={delta.key}>{delta.label || delta.key}</dt>
161	          <dd>
162	            <span className="was">{delta.preset}</span>
163	            <span aria-hidden="true"> → </span>
164	            <span className="now">{delta.value}</span>
165	            {/* The count in the eyebrow is only worth trusting if opening the
166	                card says which ones it meant. Separated the way the facts line
167	                separates its clauses: without the dot it reads as part of the
168	                value, which is the one thing this row must not blur. */}
169	            {delta.origin === 'user' && <span className="yours"> · yours</span>}
170	          </dd>
171	        </div>
172	      ))}
173	    </dl>
174	  );
175	}
