177	export function SetupCard({ context, expanded, onToggle, working, historical = false, savedAt,
178	  onCompute, attention, recentChange, sentSnapshot }: SetupCardProps) {
179	  if (!context) return null;
180	  if (context.appliedSetup !== undefined || historical)
181	    return <AppliedSetupCard context={context} historical={historical} savedAt={savedAt}
182	      expanded={expanded} working={!!working} onToggle={onToggle} onCompute={onCompute} attention={attention}
183	      recentChange={recentChange} sentSnapshot={sentSnapshot} />;
184	  const model = cardModel(context);
185	
186	  // Nothing was delegated and nothing has moved: what is left is a label, and
187	  // a label does not need a card, a border, or a heading over it.
188	  if (!model.kicker && !historical && context.planValidity !== 'needs_reassessment') {
189	    // Still the plan line even when it is only a label, so it names both the
190	    // preset and the material the plan is written against.
191	    const label = [model.preset, model.material].filter(Boolean).join(' · ');
192	    return label
193	      ? <div className={working ? 'current-setup bare working' : 'current-setup bare'} data-testid="current-setup">{label}</div>
194	      : null;
195	  }
196	
197	  return (
198	    <section className={['current-setup', working ? 'working' : '', model.outOfDate ? 'out-of-date' : ''].filter(Boolean).join(' ')}
199	      data-testid="current-setup"
200	      aria-label={historical ? 'Earlier setup — saved with this conversation' : 'Current setup'} aria-busy={working || undefined}>
201	      <p className="current-setup-eyebrow">
202	        <span>{historical ? 'Earlier setup — saved with this conversation' : 'Current setup'}</span>
203	        {/* Out of date is a legitimate state, not an error: the card is not
204	            broken, it simply will not stand behind the number any more. */}
205	        {model.outOfDate && <span className="current-setup-status out-of-date">· out of date</span>}
206	        {/* The eyebrow's right half is where a state says its one word, so only
207	            one may speak. "working…" is about this second and outranks the
208	            count, which is standing context and will still be there after. */}
209	        {working && <span className="current-setup-status">working…</span>}
210	        {!working && model.yours > 0 && (
211	          <span className="current-setup-status yours">+ {model.yours} yours</span>
212	        )}
213	        {model.deltaLabel && (
214	          <button
215	            type="button"
216	            className="current-setup-chevron"
217	            aria-label={expanded ? 'Hide the changes' : 'Show the changes'}
218	            aria-expanded={expanded}
219	            data-testid="current-setup-chevron"
220	            onClick={onToggle}
221	          >
222	            <span className={`jp-icon jp-icon-chevron-${expanded ? 'up' : 'down'}`} aria-hidden="true" />
223	          </button>
224	        )}
225	      </p>
226	      {historical && !model.kicker && <p className="current-setup-summary">
227	        {[model.preset, model.material].filter(Boolean).join(' · ') || 'No setup details were saved.'}
228	      </p>}
229	      {model.title && <p className="current-setup-title" title={model.title}>{model.title}</p>}
230	      {model.identity && <p className="current-setup-identity" title={model.identity}>{model.identity}</p>}
231	      {model.summary && <p className="current-setup-summary">{model.summary}</p>}
232	      {context.planValidity === 'needs_reassessment' && <p className="current-setup-note">
233	        Plan needs reassessment{context.planInvalidatedBy ? `: ${context.planInvalidatedBy}` : '.'}
234	      </p>}
235	      {/* The row is omitted, not left blank: a sliced plate with no usable
236	          estimate and an untouched preset has nothing to put on this line. */}
237	      {(model.facts.length > 0 || model.deltaLabel || model.struckEstimate) && <p className="current-setup-cost">
238	        <span className="clauses">
239	          {/* Struck through rather than removed: you are usually watching for
240	              the difference, and a blank kills the comparison. */}
241	          {model.struckEstimate && <span className="superseded">{model.struckEstimate}</span>}
242	          {model.struckEstimate && model.inlineNote && ' '}
243	          {model.inlineNote && <span className="estimate-note">{model.inlineNote}</span>}
244	          {model.struckEstimate && model.facts.length > 0 &&
245	            <span className="sep" aria-hidden="true"> · </span>}
246	          {model.facts.map((fact, index) => (
247	            <span key={index}>
248	              {index > 0 && <span className="sep" aria-hidden="true"> · </span>}
249	              {fact}
250	            </span>
251	          ))}
252	          {model.facts.length > 0 && model.deltaLabel &&
253	            <span className="sep" aria-hidden="true"> · </span>}
254	        </span>
255	        {/* The count is the handle: a label exists exactly when there are
256	            deltas to open, so this never offers an empty list. */}
257	        {model.deltaLabel && (
258	          <button
259	            type="button"
260	            className="current-setup-handle"
261	            aria-expanded={expanded}
262	            data-testid="current-setup-handle"
263	            onClick={onToggle}
264	          >
265	            {model.deltaLabel}
266	          </button>
267	        )}
268	      </p>}
269	      {/* Plain language, then the action. "re-slice" is the thing to do, so it
270	          reads as a link rather than as more prose. */}
271	      {model.outOfDate && (
272	        <p className="current-setup-note">
273	          {model.reason && <span>{model.reason} — </span>}
274	          <span className="action">re-slice</span>
275	        </p>
276	      )}
277	      {expanded && model.deltaLabel && (
278	        // The same card, grown. The thread behind it dims rather than going
279	        // away, so the conversation is still legibly there while you read.
280	        <div data-testid="current-setup-expansion">
281	          <DeltaList deltas={model.deltas} />
282	          {/* What the deltas are measured against, so the list means
283	              something on its own. */}
284	          {model.preset && <p className="current-setup-base">on {model.preset}</p>}
285	        </div>
286	      )}
287	    </section>
288	  );
289	}
