/* Every color, radius, and type metric below resolves through a custom
   property that tokens.ts writes from resources/jusprin/ui/design-tokens.json:
   --<group>-<name> for colors, --radius-<name> for radii, --font-<role> for
   the `font` shorthand of each type role and --font-code for code. Padding,
   margin, and gap stay literal but must sit on the spacing scale. styles.test.ts
   fails the build on any literal outside those rules. */

/* The product font ships with OrcaSlicer, but it is registered as a private
   font of the native process and WKWebView renders in a separate process
   that cannot see it. A Latin subset is embedded so the Agent page uses the
   same face as the native shell; CJK text falls through to the system font. */
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 400;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Regular_latin.woff') format('woff');
}
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 700;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Bold_latin.woff') format('woff');
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font: var(--font-body);
  color: var(--text-primary);
  background: var(--surface-subtle);
  -webkit-user-select: text;
  user-select: text;
}

.app {
  position: relative;
  min-width: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100%;
}

:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* Compact workspace context header */
.context-summary {
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-canvas);
  font: var(--font-label);
  color: var(--text-secondary);
}

.context-summary .project {
  color: var(--text-primary);
  font: var(--font-label-bold);
}

/* Current setup card. Measured from the Figma "Current Setup Card" page:
   a 405px card inset 12px inside a 429px dock, tinted surface/subtle with a
   2px action/primary edge, container radius, 16/12 padding and a 4px row gap.
   The compact rows keep settings and print facts readable; expansion grows the same
   card rather than floating a second panel under it. */
.pinned-setup {
  flex: 0 0 auto;
  padding: 12px;
  background: var(--surface-canvas);
}

.current-setup {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-container);
  background: var(--surface-subtle);
}

/* The degenerate case: nothing delegated, nothing sliced, preset untouched.
   A label is not a card, so it keeps the slot but drops the frame. */
.current-setup.bare {
  padding: 0 4px;
  border: 0;
  border-radius: 0;
  background: transparent;
  font: var(--font-metadata);
  color: var(--text-secondary);
}

.current-setup p {
  margin: 0;
}

/* Eyebrow in Dense Metadata, action/primary. The right half is where a state
   puts its one word -- "working...", "+2 yours", "undo" -- so nothing else may
   live there. */
.current-setup-eyebrow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font: var(--font-metadata);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--action-primary);
  /* One line, always. Measured at the dock's real width -- which narrows with
     the window, well below the 429px design frame -- a three-digit count wraps
     the heading and the card silently grows a row. The fixed word gives up a
     few pixels instead, because losing height is worse than losing them. */
  white-space: nowrap;
}

.current-setup-eyebrow > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Mid-thought: everything drops to secondary, nothing is removed. The numbers
   on screen are still what Slice would produce this second. */
.current-setup.working .current-setup-title,
.current-setup.working .current-setup-identity {
  color: var(--text-secondary);
}

.current-setup.working.bare {
  opacity: 0.7;
}

/* The figure the plate can no longer defend. Kept legible: it is the number
   the reader is comparing the new one against. */
.current-setup-cost .superseded {
  text-decoration: line-through;
  opacity: 0.7;
}

/* Out of date drops the edge entirely, as the design has it: the card is not
   asking for attention, it is standing down from a number it cannot defend.
   Transparent rather than removed so the box keeps its size. */
.current-setup.out-of-date {
  border-color: transparent;
}

/* Why it went, then what to do. Its own row: the dock narrows with the window,
   well below the 429px design frame, and sharing the facts line cost this its
   second half in the running app. A truncated instruction is worse than 16px. */
.current-setup-note {
  font: var(--font-metadata);
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Colour alone marks the action, as it does on every other accent control in
   the panel. */
.current-setup-note .action {
  color: var(--action-primary);
}

.current-setup-eyebrow .out-of-date {
  color: var(--status-warning);
}

/* The one word a state gets, hard right in the eyebrow, before the chevron. */
.current-setup-status {
  margin-left: auto;
  text-transform: none;
  letter-spacing: 0;
}

/* Body Bold, text/primary. One line, always: 40 characters is a contract with the
   agent, and all the card can do is stop a long one from breaking the layout
   -- the full sentence lives in the expansion. */
.current-setup-title {
  font: var(--font-label);
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* The preset name standing in for a title it does not have. */
.current-setup-identity {
  font: var(--font-body-small-bold);
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.current-setup-summary,
.current-setup-intent {
  font: var(--font-label);
  color: var(--text-secondary);
}
.current-setup-summary {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Metadata, text/secondary. One line: the clauses give way before the
   handle does, because the handle is the only way into the expansion. */
.current-setup-cost {
  display: flex;
  align-items: baseline;
  white-space: nowrap;
  font: var(--font-metadata);
  color: var(--text-secondary);
}

.current-setup-cost .clauses {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.current-setup-cost .sep {
  opacity: 0.6;
}

.current-setup-handle {
  flex: 0 0 auto;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  color: inherit;
  cursor: pointer;
}

.current-setup-handle:hover {
  color: var(--text-primary);
}

.current-setup-chevron {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 16px;
  margin: 0 -4px 0 0;
  padding: 0;
  border: 0;
  border-radius: var(--radius-standard);
  background: none;
  font: var(--font-metadata);
  color: var(--action-primary);
  cursor: pointer;
}

.current-setup-chevron:hover {
  background: var(--surface-selected);
}

/* The deltas grow the card. They are a temporary layer over the thread, which
   dims rather than disappearing, so the conversation is still legibly there. */
.current-setup-deltas {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  margin: 4px 0 0;
  font: var(--font-metadata);
  color: var(--text-secondary);
}

.current-setup-deltas > div {
  display: contents;
}

.current-setup-deltas dt {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.current-setup-deltas dd {
  margin: 0;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.current-setup-deltas .was {
  color: var(--text-secondary);
  text-decoration: line-through;
}

/* Which rows the eyebrow's count meant. Secondary rather than accented: it
   marks a row, it does not compete with the value on it. */
.current-setup-deltas .yours {
  color: var(--text-secondary);
}

.current-setup-base {
  margin-top: 4px !important;
  font: var(--font-metadata);
  color: var(--text-secondary);
}

.setup-summary-card {
  gap: 8px;
  padding: 12px;
  border-left: 2px solid var(--action-primary);
  min-width: 0;
}

.setup-summary-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font: var(--font-metadata-bold);
