import fs from 'node:fs';

const path = 'src/styles.css';
let css = fs.readFileSync(path, 'utf8').replace(/\r\n/g, '\n');

const cardStart = css.indexOf('/* Current setup card. Measured from the Figma');
const cardEnd = css.indexOf('/* The thread is dimmed, not removed');
if (cardStart < 0 || cardEnd < 0) throw new Error('card block not found');

const card = `/* Setup card. Measured from the Figma "Current Setup Card" page, sections 5
   to 7: a 405px card inset 12px inside the dock, surface/subtle, container
   radius, 12/16 padding and a 4px row gap. A live card carries a 2px
   action/primary edge and an action/primary header; a saved or out-of-date
   card drops the edge and greys the header. Expansion grows the same card
   rather than floating a second panel under it. */
.pinned-setup {
  flex: 0 0 auto;
  padding: 12px;
  background: var(--surface-canvas);
}

.setup-card {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding: 12px 16px;
  border-radius: var(--radius-container);
  background: var(--surface-subtle);
}

/* Drawn inside the box, as Figma's stroke is: the edge follows the corner
   radius and takes no width from the rows. */
.setup-card--live {
  box-shadow: inset 2px 0 0 var(--action-primary);
}

.setup-card p,
.setup-card h2,
.setup-card h3,
.setup-card dl,
.setup-card dd,
.setup-card ul {
  margin: 0;
}

/* Header in Metadata Bold: what the card is on the left, the one state it is
   in on the right. One line, always: the dock narrows with the window, and a
   wrapped header silently costs the thread a row. The label gives way. */
.setup-card-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-metadata-bold);
  color: var(--text-secondary);
  white-space: nowrap;
}

.setup-card--live .setup-card-header {
  color: var(--action-primary);
}

.setup-card-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.setup-card-state {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
}

/* Body Bold, one line. The whole sentence is in the tooltip. */
.setup-card-title {
  font: var(--font-body-bold);
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.setup-card-line {
  font: var(--font-label);
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

.setup-card-heading {
  font: var(--font-metadata-bold);
  color: var(--text-primary);
}

/* Time, material, plate. They wrap as whole clauses at a narrow dock. */
.setup-card-metrics {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  font: var(--font-label-bold);
  color: var(--text-primary);
}

.setup-card-metric {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.setup-card-metric .jp-icon,
.setup-card-info .jp-icon,
.setup-card-state .jp-icon {
  color: var(--text-secondary);
}

.setup-card-divider {
  flex: 0 0 auto;
  width: 100%;
  height: 1px;
  margin: 0;
  border: 0;
  background: var(--border-subtle);
}

.setup-card-attention {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.setup-card-warning {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-metadata-bold);
  color: var(--text-primary);
}

/* Colour is never the only signal: the row always has its icon and words. */
.setup-card-warning .jp-icon {
  color: var(--status-warning);
}

.setup-card-info {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-label);
  color: var(--text-secondary);
}

.setup-card-info > span:last-child {
  min-width: 0;
  overflow-wrap: anywhere;
}

/* The design system's Button/Link: text only, Label Bold, action/primary. */
.setup-card-link {
  align-self: flex-start;
  height: 26px;
  padding: 0 4px;
  border: 0;
  border-radius: var(--radius-standard);
  background: none;
  font: var(--font-label-bold);
  color: var(--action-primary);
  cursor: pointer;
}

.setup-card-link:hover {
  color: var(--action-primary-hover);
  text-decoration: underline;
}

.setup-card-link:active {
  color: var(--action-primary-pressed);
}

/* The design system's Disclosure header: one 28px target for the whole row. */
.setup-card-disclosure {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-standard);
  background: none;
  font: var(--font-label-bold);
  color: var(--text-secondary);
  text-align: left;
  cursor: pointer;
}

.setup-card-disclosure:hover {
  color: var(--text-primary);
}

.setup-card-details,
.setup-card-section,
.setup-card-rows,
.setup-card-override {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.setup-card h3 {
  font: var(--font-label-bold);
  color: var(--text-secondary);
}

/* Name left, value right. A long value wraps under itself, still right. */
.setup-card-row {
  display: flex;
  align-items: baseline;
  gap: 4px;
  padding: 4px 0;
  font: var(--font-metadata);
}

.setup-card-row dt {
  flex: 0 0 auto;
  color: var(--text-secondary);
}

.setup-card-row dd {
  flex: 1 1 auto;
  min-width: 0;
  text-align: right;
  color: var(--text-primary);
  overflow-wrap: anywhere;
}

.setup-card-note {
  font: var(--font-metadata);
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

.setup-card-object {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding: 4px 0;
}

.setup-card-object-name {
  font: var(--font-metadata-bold);
  color: var(--text-primary);
  overflow-wrap: anywhere;
}

.setup-card-object-values,
.setup-card-override-target {
  font: var(--font-metadata);
  color: var(--text-primary);
  overflow-wrap: anywhere;
}

.setup-card-override-target {
  padding: 4px 0;
}

.setup-card-sent {
  font: var(--font-metadata-bold);
  color: var(--text-secondary);
}

.setup-card-findings {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0;
  list-style: none;
  font: var(--font-metadata);
  color: var(--text-secondary);
}

.setup-card-findings li {
  display: flex;
  flex-direction: column;
}

.setup-card-findings strong {
  color: var(--text-primary);
}

`;
css = css.slice(0, cardStart) + card + css.slice(cardEnd);

const noticeStart = css.indexOf('.historical-chat-notice {');
const noticeEnd = css.indexOf('/* Conversation */');
if (noticeStart < 0 || noticeEnd < 0) throw new Error('notice block not found');
const notice = `/* The end of an earlier chat. Figma section 5, "Project updates · Locked
   continuation": the same quiet surface as a saved card, with no edge, and
   the locked field where the composer would be. */
.project-updates {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
  gap: 4px;
  margin: 12px;
  padding: 12px 16px;
  border-radius: var(--radius-container);
  background: var(--surface-subtle);
}

.project-updates p {
  margin: 0;
}

.project-updates-divider {
  width: 100%;
  height: 1px;
  margin: 0;
  border: 0;
  background: var(--border-subtle);
}

.project-updates-title {
  font: var(--font-body-bold);
  color: var(--text-primary);
}

.project-updates-detail {
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.project-updates-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.project-updates-actions button.primary {
  border-radius: var(--radius-container);
  font: var(--font-body-small-bold);
}

.project-updates-link {
  height: 26px;
  padding: 0 4px;
  border: 0;
  border-radius: var(--radius-standard);
  background: none;
  font: var(--font-label-bold);
  color: var(--action-primary);
  cursor: pointer;
}

.project-updates-link:hover {
  color: var(--action-primary-hover);
  text-decoration: underline;
}

.project-updates-link:active {
  color: var(--action-primary-pressed);
}

/* Locked, not merely greyed: the host refuses a send from an earlier chat as
   well. The field stays so the place to continue is still where it was. */
.project-updates-locked {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 16px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-standard);
  background: var(--surface-subtle);
  color: var(--text-secondary);
}

.project-updates-locked input {
  flex: 1 1 auto;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  font: var(--font-body-small);
  color: var(--action-disabled-text);
}

.project-updates-locked input::placeholder {
  color: var(--action-disabled-text);
  opacity: 1;
}

`;
css = css.slice(0, noticeStart) + notice + css.slice(noticeEnd);

const icons = ['clock', 'package', 'grid-3x3', 'info', 'triangle-alert', 'lock'];
const anchor = ".jp-icon-close { -webkit-mask-image: url('@resources/jusprin/ui/icons/close.svg'); mask-image: url('@resources/jusprin/ui/icons/close.svg'); }\n";
if (!css.includes(anchor)) throw new Error('icon anchor not found');
css = css.replace(anchor, anchor + icons.map((name) =>
  `.jp-icon-${name} { -webkit-mask-image: url('@resources/jusprin/ui/icons/${name}.svg'); mask-image: url('@resources/jusprin/ui/icons/${name}.svg'); }\n`).join(''));

fs.writeFileSync(path, css);
console.log('ok', css.length);

