import fs from 'node:fs';

const path = 'src/App.tsx';
let s = fs.readFileSync(path, 'utf8').replace(/\r\n/g, '\n');
const swap = (from, to) => {
  if (!s.includes(from)) throw new Error('missing: ' + from.slice(0, 90));
  s = s.replace(from, to);
};
const cut = (start, end, to) => {
  const a = s.indexOf(start);
  const b = s.indexOf(end, a);
  if (a < 0 || b < 0) throw new Error('missing range: ' + start.slice(0, 60));
  s = s.slice(0, a) + to + s.slice(b);
};

swap(`import { AttachmentSource, Envelope } from './bridge/protocol';`,
