import fs from 'node:fs';
const edit = (p, pairs) => {
  let s = fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n');
  for (const [a, b] of pairs) { if (!s.includes(a)) throw new Error(p + ' missing ' + a.slice(0, 80)); s = s.replace(a, b); }
  fs.writeFileSync(p, s);
};

